package com.ruoyi.medical.persistence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.ruoyi.medical.contracts.*;
import java.math.*;import java.time.*;import java.util.*;
import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;

/** Factual post-send accounting. Only registered, authenticated capture evidence can determine usage. */
public final class FormalInvocationSettlement {
 private final JdbcTemplate db;private final FormalInvocationSchema schema;
 private final FormalVerificationJobs jobs;private final TaskInvocationRecords tasks;private TaskPlanDraftInvocationRecords planDrafts;private TaskSectionWriterInvocationRecords sectionWriters;private TaskSourceVerifierInvocationRecords sourceVerifiers;private DocumentReviewInvocationRecords documentReviews;private final FormalInvocationObjectRegistration objects;private final FormalInvocationReservations originalReservations;
 private FormalEvaluationInvocationRecords evaluations;
 @org.springframework.beans.factory.annotation.Autowired(required=false) void evaluationAdapter(FormalEvaluationInvocationRecords records){if(evaluations!=null)throw new IllegalStateException("EVALUATION_ADAPTER_ALREADY_BOUND");evaluations=Objects.requireNonNull(records);}

 public FormalInvocationSettlement(DataSource data,FormalInvocationSchema schema,FormalVerificationJobs jobs,FormalInvocationObjectRegistration objects,FormalInvocationReservations originalReservations){this(data,schema,jobs,objects,originalReservations,null);}
 public FormalInvocationSettlement(DataSource data,FormalInvocationSchema schema,FormalVerificationJobs jobs,FormalInvocationObjectRegistration objects,FormalInvocationReservations originalReservations,TaskInvocationRecords tasks){this.originalReservations=originalReservations;db=new JdbcTemplate(data);db.setQueryTimeout(5);this.schema=schema;this.jobs=jobs;this.objects=objects;this.tasks=tasks;}
 public FormalInvocationSettlement(DataSource data,FormalInvocationSchema schema,FormalVerificationJobs jobs,FormalInvocationObjectRegistration objects,FormalInvocationReservations originalReservations,TaskInvocationRecords tasks,TaskPlanDraftInvocationRecords planDrafts){this(data,schema,jobs,objects,originalReservations,tasks);this.planDrafts=Objects.requireNonNull(planDrafts);}
 public FormalInvocationSettlement(DataSource data,FormalInvocationSchema schema,FormalVerificationJobs jobs,FormalInvocationObjectRegistration objects,FormalInvocationReservations originalReservations,TaskInvocationRecords tasks,TaskPlanDraftInvocationRecords planDrafts,TaskSectionWriterInvocationRecords sectionWriters){this(data,schema,jobs,objects,originalReservations,tasks);this.planDrafts=planDrafts;this.sectionWriters=Objects.requireNonNull(sectionWriters);}
 public FormalInvocationSettlement(DataSource data,FormalInvocationSchema schema,FormalVerificationJobs jobs,FormalInvocationObjectRegistration objects,FormalInvocationReservations originalReservations,TaskInvocationRecords tasks,TaskPlanDraftInvocationRecords planDrafts,TaskSectionWriterInvocationRecords sectionWriters,TaskSourceVerifierInvocationRecords sourceVerifiers){this(data,schema,jobs,objects,originalReservations,tasks);this.planDrafts=planDrafts;this.sectionWriters=sectionWriters;this.sourceVerifiers=Objects.requireNonNull(sourceVerifiers);}
 public FormalInvocationSettlement(DataSource data,FormalInvocationSchema schema,FormalVerificationJobs jobs,FormalInvocationObjectRegistration objects,FormalInvocationReservations originalReservations,TaskInvocationRecords tasks,TaskPlanDraftInvocationRecords planDrafts,TaskSectionWriterInvocationRecords sectionWriters,TaskSourceVerifierInvocationRecords sourceVerifiers,DocumentReviewInvocationRecords documentReviews){this(data,schema,jobs,objects,originalReservations,tasks);this.planDrafts=planDrafts;this.sectionWriters=sectionWriters;this.sourceVerifiers=sourceVerifiers;this.documentReviews=Objects.requireNonNull(documentReviews);}
 private FormalInvocationBinding job(String tenant,String run,String invocation)throws Exception{if(evaluations!=null&&evaluations.supports(tenant,invocation))return evaluations.byInvocation(tenant,invocation);if(documentReviews!=null&&documentReviews.supports(tenant,invocation))return documentReviews.byInvocation(tenant,invocation);if(sourceVerifiers!=null&&sourceVerifiers.supports(tenant,invocation))return sourceVerifiers.byInvocation(tenant,invocation);if(sectionWriters!=null&&sectionWriters.supports(tenant,invocation))return sectionWriters.byInvocation(tenant,invocation);if(planDrafts!=null&&planDrafts.supports(tenant,run))return planDrafts.byInvocation(tenant,invocation);return tasks!=null&&tasks.supports(tenant,run)?tasks.byInvocation(tenant,invocation):new FormalInvocationBinding.Verification(jobs.byRun(tenant,run));}
 static boolean successfulResult(boolean task,String reason){return "stop".equals(reason)||task&&"tool-calls".equals(reason);}
 static boolean finishesRun(FormalInvocationBinding binding){return !binding.task()&&!(binding instanceof TaskPlanDraftInvocationRecords.Binding)&&!(binding instanceof DocumentReviewInvocationRecords.Binding)&&!(binding instanceof FormalEvaluationInvocationRecords.Binding);}
 public static final class Recorded {
  private final JsonNode receipt;private final String hash;
  private Recorded(JsonNode receipt,String hash){this.receipt=receipt.deepCopy();this.hash=hash;}
  public JsonNode receipt(){return receipt.deepCopy();}public String receiptSha256(){return hash;}
  public boolean settled(){return "SETTLED".equals(receipt.required("settlement_status").textValue());}
 }
 private record Reservation(String id,String budget,String version,BigDecimal amount,BigInteger tokens,String status,BigInteger revision){}
 Recorded record(FormalInvocationOutcomeAuthority.VerifiedOutcome outcome,FormalProviderCaptureEvidence.Verified capture,
    FormalInvocationObjectRegistration.Registered resultObject,FormalInvocationObjectRegistration.Registered captureObject)throws Exception{
  outcome.requireActive();capture.requireActive();if(tasks==null&&outcome.binding().path("canonical_request").isTextual()&&"TASK".equals(schema.parse(outcome.binding().required("canonical_request").textValue()).path("execution_kind").asText()))throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);resultObject.requireUnchanged();captureObject.requireUnchanged();
  if(!outcome.invocationId().equals(resultObject.invocationId())||!outcome.invocationId().equals(captureObject.invocationId())||!outcome.attemptId().equals(resultObject.attemptId())||!outcome.attemptId().equals(captureObject.attemptId())||!schema.canonical(outcome.result()).equals(schema.canonical(resultObject.canonicalPayload()))||!schema.canonical(capture.artifact()).equals(schema.canonical(captureObject.canonicalPayload())))bad();
  String tenant=outcome.tenantId(),invocation=outcome.invocationId();var old=read(tenant,invocation);if(old.isPresent())return old.get();
  var job=job(tenant,outcome.binding().required("run_id").textValue(),invocation);originalReservations.requireRegistered(job,invocation);
  var original=one(db.query("SELECT canonical_price,price_sha256,enterprise_reservation_id,parent_reservation_id FROM formal_invocation_binding WHERE tenant_id=? AND invocation_id=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3),r.getString(4)),tenant,invocation));
  var priceNode=schema.parse(original.get(0));if(!schema.hash(priceNode).equals(original.get(1))||!schema.canonical(schema.parse(job.dependencies()).required("price")).equals(original.get(0)))bad();
  var state=one(db.query("SELECT status,settlement_status,price_version,revision FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2 FOR UPDATE",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3),r.getString(4)),tenant,invocation));
  if(!Set.of("DISPATCHING","IN_FLIGHT","UNKNOWN","CANCEL_REQUESTED").contains(state.get(0))||!"PENDING".equals(state.get(1)))bad();
  var price=schema.price(state.get(2),priceNode);var determination=FormalInvocationAccounting.determine(price,capture.usage(),capture.confirmedCalls(),capture.providerTerminal());
  var reservations=db.query("SELECT reservation_id,budget_id,budget_revision,upper_amount,upper_tokens,status,revision FROM budget_reservation WHERE tenant_id=? AND invocation_id=? ORDER BY budget_id LIMIT 3 FOR UPDATE",(r,n)->new Reservation(r.getString(1),r.getString(2),r.getString(3),r.getBigDecimal(4),r.getBigDecimal(5).toBigIntegerExact(),r.getString(6),r.getBigDecimal(7).toBigIntegerExact()),tenant,invocation);
  if(reservations.size()!=2||!Set.of(original.get(2),original.get(3)).equals(new HashSet<>(reservations.stream().map(Reservation::id).toList()))||reservations.stream().anyMatch(r->!r.status.equals("RESERVED")))bad();
  boolean known=determination.maySettleAll();boolean over=known&&reservations.stream().anyMatch(r->determination.amount().orElseThrow().compareTo(r.amount)>0||determination.tokens().orElseThrow().compareTo(r.tokens)>0);
  String settlement=over?"DISPUTED":known?"SETTLED":"PENDING";
  String status=!known||over?"UNKNOWN":"CANCEL_REQUESTED".equals(state.get(0))?"CANCELLED":successfulResult(job.task()||job instanceof FormalEvaluationInvocationRecords.Binding,outcome.result().required("reason").required("kind").textValue())?"SUCCEEDED":"FAILED";
  var now=one(db.query("SELECT UTC_TIMESTAMP(6)",(r,n)->r.getTimestamp(1).toLocalDateTime()));
  var admitted=one(db.query("SELECT admitted_at FROM formal_invocation_attempt WHERE tenant_id=? AND invocation_id=? AND attempt_id=? LIMIT 2",(r,n)->r.getTimestamp(1).toLocalDateTime(),tenant,invocation,outcome.attemptId()));if(admitted.isAfter(now))bad();
  ObjectNode receipt=new com.fasterxml.jackson.databind.ObjectMapper().createObjectNode().put("schema_version","1.0.0").put("tenant_id",tenant).put("project_id",job.project()).put("invocation_id",invocation).put("verification_id",job.verification()).put("attempt_id",outcome.attemptId()).put("usage_receipt_id",capture.receiptId()).put("request_sha256",job.requestHash()).put("input_sha256",job.inputHash()).put("price_version",price.priceVersion()).put("currency",price.currency()).put("status",status).put("settlement_status",settlement).put("provider_terminal",capture.providerTerminal()).put("verified_at",admitted.toInstant(ZoneOffset.UTC).toString()).put("recorded_at",now.toInstant(ZoneOffset.UTC).toString()).put("created_by",job.actor()).put("classification",job.classification()).put("result_registration_sha256",resultObject.objectReceiptSha256()).put("capture_registration_sha256",captureObject.objectReceiptSha256());
  if(job instanceof FormalEvaluationInvocationRecords.Binding evaluation)receipt.put("execution_kind","SYSTEM_JOB").put("job_type","EVALUATION_VERIFICATION");if(job.task())receipt.put("execution_kind","TASK");if(job instanceof TaskPlanDraftInvocationRecords.Binding)receipt.put("execution_kind","SYSTEM_JOB").put("job_type","PLAN_DRAFT");if(job instanceof DocumentReviewInvocationRecords.Binding)receipt.put("execution_kind","SYSTEM_JOB").put("job_type","CHECK_DOCUMENT").put("node_kind","N07");receipt.set("result_artifact",schema.parse(schema.canonical(resultObject.artifact())));receipt.set("capture_artifact",schema.parse(schema.canonical(captureObject.artifact())));
  if(determination.amount().isPresent())receipt.put("known_amount",determination.amount().get().toPlainString());else receipt.putNull("known_amount");if(determination.tokens().isPresent())receipt.put("known_tokens",determination.tokens().get().toString());else receipt.putNull("known_tokens");if(determination.calls().isPresent())receipt.put("known_calls",determination.calls().get().toString());else receipt.putNull("known_calls");
  if("SETTLED".equals(settlement))receipt.put("settled_at",now.toInstant(ZoneOffset.UTC).toString());else receipt.putNull("settled_at");
  String raw=schema.canonical(receipt),hash=schema.hash(receipt);
  var receiptRow=metadata(job,now);receiptRow.put("receipt_id",capture.receiptId());receiptRow.put("invocation_id",invocation);receiptRow.put("kind","PROVIDER_CAPTURE");receiptRow.put("receipt_ref",schema.canonical(captureObject.artifact()));receiptRow.put("receipt_artifact_id",captureObject.artifact().artifactId());receiptRow.put("receipt_sha256",captureObject.artifact().sha256());receiptRow.put("received_at",now);insert("invocation_receipt",receiptRow);
  if(known){
   for(var r:reservations){var account=one(db.query("SELECT revision,reserved,reserved_tokens,reserved_calls FROM budget_account WHERE tenant_id=? AND budget_id=? LIMIT 2 FOR UPDATE",(rs,n)->List.of(rs.getBigDecimal(1),rs.getBigDecimal(2),rs.getBigDecimal(3),rs.getBigDecimal(4)),tenant,r.budget));
    if(account.get(1).compareTo(r.amount)<0||account.get(2).toBigIntegerExact().compareTo(r.tokens)<0||account.get(3).signum()<1)bad();
    if(!over){changed(db.update("UPDATE budget_account SET reserved=reserved-?,reserved_tokens=reserved_tokens-?,reserved_calls=reserved_calls-1,spent=spent+?,spent_tokens=spent_tokens+?,spent_calls=spent_calls+?,revision=revision+1,updated_at=? WHERE tenant_id=? AND budget_id=? AND revision=?",r.amount,r.tokens,determination.amount().orElseThrow(),determination.tokens().orElseThrow(),determination.calls().orElseThrow(),now,tenant,r.budget,account.get(0)));}
    changed(db.update("UPDATE budget_reservation SET status=?,settlement_receipt_id=?,settled_amount=?,settled_tokens=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND reservation_id=? AND status='RESERVED' AND revision=?",over?"DISPUTED":"SETTLED",capture.receiptId(),determination.amount().orElseThrow(),determination.tokens().orElseThrow(),now,tenant,r.id,r.revision));
   }
  }
  changed(db.update("UPDATE invocation SET status=?,settlement_status=?,result_artifact_id=?,result_sha256=?,usage_receipt_id=?,settled_amount=?,total_tokens=?,provider_request_id=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND invocation_id=? AND revision=? AND settlement_status='PENDING'",status,settlement,resultObject.artifact().artifactId(),resultObject.artifact().sha256(),capture.receiptId(),"SETTLED".equals(settlement)?determination.amount().orElseThrow():null,"SETTLED".equals(settlement)?determination.tokens().orElseThrow():null,outcome.result().required("provider_request_id").isNull()?null:outcome.result().required("provider_request_id").textValue(),now,tenant,invocation,state.get(3)));
  if("SETTLED".equals(settlement)&&finishesRun(job)){String stepStatus="SUCCEEDED".equals(status)?"SUCCEEDED":"CANCELLED".equals(status)?"CANCELLED":"FAILED";changed(db.update("UPDATE run_step SET status=?,output_ref=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND step_id=? AND status='RUNNING'",stepStatus,schema.canonical(resultObject.artifact()),now,tenant,job.run(),job.step()));changed(db.update("UPDATE system_job_run SET status=?,ended_at=?,revision=revision+1,updated_at=? WHERE tenant_id=? AND run_id=? AND status='RUNNING'",stepStatus,now,now,tenant,job.run()));}
  var row=metadata(job,now);row.put("invocation_id",invocation);row.put("receipt_id",capture.receiptId());row.put("receipt_json",raw);row.put("receipt_sha256",hash);insert("formal_invocation_accounting",row);
  var audit=metadata(job,now);audit.put("audit_id",UUID.randomUUID().toString());audit.put("subject_id",job.actor());audit.put("action","model.invocation_accounted");audit.put("resource_ref",raw);audit.put("result","SUCCESS");audit.put("request_id",capture.receiptId());audit.put("trace_id",invocation);insert("audit_event",audit);insert("outbox_event",Map.of("tenant_id",tenant,"event_id",UUID.randomUUID().toString(),"aggregate_id",capture.receiptId(),"aggregate_revision",1,"event_type","model.invocation_accounted","payload",raw,"occurred_at",now));outcome.requireActive();return read(tenant,invocation).orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));
 }
 Optional<Recorded> read(String tenant,String invocation)throws Exception{
  if(!TenantScope.requireCurrent().tenantId().equals(tenant))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var rows=db.query("SELECT receipt_json,receipt_sha256 FROM formal_invocation_accounting WHERE tenant_id=? AND invocation_id=? AND schema_version='1.0.0' AND schema_manifest_sha256=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2)),tenant,invocation,schema.manifestSha256());if(rows.size()>1)bad();if(rows.isEmpty())return Optional.empty();String raw=rows.get(0).get(0),hash=rows.get(0).get(1);var r=schema.parse(raw);if("TASK".equals(r.path("execution_kind").asText())&&tasks==null)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);if(!hash.equals(schema.hash(r))||!raw.equals(schema.canonical(r))||!tenant.equals(text(r,"tenant_id"))||!invocation.equals(text(r,"invocation_id")))bad();
  var result=objects.registered(tenant,invocation,"MODEL_RESULT").orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));var capture=objects.registered(tenant,invocation,"PROVIDER_CAPTURE").orElseThrow(()->new TenantAccessException(ErrorCode.CONTENT_MISMATCH));if(!result.objectReceiptSha256().equals(text(r,"result_registration_sha256"))||!capture.objectReceiptSha256().equals(text(r,"capture_registration_sha256"))||!schema.canonical(result.artifact()).equals(schema.canonical(r.required("result_artifact")))||!schema.canonical(capture.artifact()).equals(schema.canonical(r.required("capture_artifact"))))bad();
  var run=one(db.query("SELECT run_id FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(rs,n)->rs.getString(1),tenant,invocation));var job=job(tenant,run,invocation);originalReservations.requireRegistered(job,invocation);if(!job.verification().equals(text(r,"verification_id"))||!job.requestHash().equals(text(r,"request_sha256"))||!job.inputHash().equals(text(r,"input_sha256"))||!job.actor().equals(text(r,"created_by"))||!job.project().equals(text(r,"project_id")))bad();
  String receipt=text(r,"usage_receipt_id"),actor=text(r,"created_by"),project=text(r,"project_id");LocalDateTime now=LocalDateTime.ofInstant(Instant.parse(text(r,"recorded_at")),ZoneOffset.UTC);
  if(one(db.query("SELECT COUNT(*) FROM invocation_receipt WHERE tenant_id=? AND project_id=? AND receipt_id=? AND invocation_id=? AND kind='PROVIDER_CAPTURE' AND receipt_artifact_id=? AND receipt_sha256=? AND received_at=? AND created_by=? AND created_at=? AND schema_version='1.0.0' AND schema_manifest_sha256=? AND classification=?",(rs,n)->rs.getInt(1),tenant,project,receipt,invocation,capture.artifact().artifactId(),capture.artifact().sha256(),now,actor,now,schema.manifestSha256(),text(r,"classification")))!=1)bad();var ref=one(db.query("SELECT receipt_ref FROM invocation_receipt WHERE tenant_id=? AND receipt_id=? LIMIT 2",(rs,n)->rs.getString(1),tenant,receipt));if(!schema.canonical(capture.artifact()).equals(schema.canonical(schema.parse(ref))))bad();
  if(one(db.query("SELECT COUNT(*) FROM formal_invocation_accounting WHERE tenant_id=? AND project_id=? AND invocation_id=? AND receipt_id=? AND receipt_sha256=? AND created_by=? AND created_at=? AND classification=?",(rs,n)->rs.getInt(1),tenant,project,invocation,receipt,hash,actor,now,text(r,"classification")))!=1)bad();
  var actual=one(db.query("SELECT status,settlement_status,price_version,currency,result_artifact_id,result_sha256,usage_receipt_id,settled_amount,total_tokens FROM invocation WHERE tenant_id=? AND invocation_id=? LIMIT 2",(rs,n)->Arrays.asList(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4),rs.getString(5),rs.getString(6),rs.getString(7),rs.getString(8),rs.getString(9)),tenant,invocation));
  if(!actual.subList(0,7).equals(List.of(text(r,"status"),text(r,"settlement_status"),text(r,"price_version"),text(r,"currency"),result.artifact().artifactId(),result.artifact().sha256(),receipt)))bad();
  boolean settled="SETTLED".equals(text(r,"settlement_status"));if(settled){if(actual.get(7)==null||new BigDecimal(actual.get(7)).compareTo(new BigDecimal(text(r,"known_amount")))!=0||!Objects.equals(actual.get(8),text(r,"known_tokens"))||!text(r,"settled_at").equals(text(r,"recorded_at")))bad();}else if(actual.get(7)!=null||actual.get(8)!=null||!r.required("settled_at").isNull())bad();
  var admitted=one(db.query("SELECT admitted_at FROM formal_invocation_attempt WHERE tenant_id=? AND invocation_id=? AND attempt_id=? LIMIT 2",(rs,n)->rs.getTimestamp(1).toLocalDateTime(),tenant,invocation,text(r,"attempt_id")));if(!admitted.toInstant(ZoneOffset.UTC).toString().equals(text(r,"verified_at")))bad();
  var reservationStates=db.query("SELECT status,settlement_receipt_id,settled_amount,settled_tokens FROM budget_reservation WHERE tenant_id=? AND invocation_id=? ORDER BY budget_id LIMIT 3",(rs,n)->Arrays.asList(rs.getString(1),rs.getString(2),rs.getString(3),rs.getString(4)),tenant,invocation);if(reservationStates.size()!=2)bad();for(var reserved:reservationStates){String expected="PENDING".equals(text(r,"settlement_status"))?"RESERVED":text(r,"settlement_status");if(!expected.equals(reserved.get(0)))bad();if(expected.equals("RESERVED")){if(reserved.get(1)!=null||reserved.get(2)!=null||reserved.get(3)!=null)bad();}else if(!receipt.equals(reserved.get(1))||reserved.get(2)==null||new BigDecimal(reserved.get(2)).compareTo(new BigDecimal(text(r,"known_amount")))!=0||!Objects.equals(reserved.get(3),text(r,"known_tokens")))bad();}
  var audit=one(db.query("SELECT resource_ref FROM audit_event WHERE tenant_id=? AND project_id=? AND subject_id=? AND created_by=? AND action='model.invocation_accounted' AND result='SUCCESS' AND request_id=? AND trace_id=? AND created_at=? AND schema_manifest_sha256=? LIMIT 2",(rs,n)->rs.getString(1),tenant,project,actor,actor,receipt,invocation,now,schema.manifestSha256()));var event=one(db.query("SELECT payload FROM outbox_event WHERE tenant_id=? AND aggregate_id=? AND aggregate_revision=1 AND event_type='model.invocation_accounted' AND occurred_at=? LIMIT 2",(rs,n)->rs.getString(1),tenant,receipt,now));if(!raw.equals(schema.canonical(schema.parse(audit)))||!raw.equals(schema.canonical(schema.parse(event))))bad();return Optional.of(new Recorded(r,hash));
 }
 private Map<String,Object> metadata(FormalInvocationBinding job,LocalDateTime now){var v=new LinkedHashMap<String,Object>();v.put("tenant_id",job.tenant());v.put("project_id",job.project());v.put("schema_version","1.0.0");v.put("schema_manifest_sha256",schema.manifestSha256());v.put("created_by",job.actor());v.put("created_at",now);v.put("classification",job.classification());return v;}
 private void insert(String table,Map<String,Object> v){var keys=new ArrayList<>(v.keySet());changed(db.update("INSERT INTO "+table+" ("+String.join(",",keys)+") VALUES ("+String.join(",",Collections.nCopies(keys.size(),"?"))+")",keys.stream().map(v::get).toArray()));}
 private static String text(JsonNode n,String k){var v=n.required(k);if(!v.isTextual())bad();return v.textValue();}private static void changed(int n){if(n!=1)throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);}private static <T>T one(List<T> r){if(r.size()!=1||r.get(0)==null)bad();return r.get(0);}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
